UPDATE git_credentials SET credential_type=#{type},display_name=#{displayName},server_url=#{serverUrl}, username=#{username},updated_by=#{actorId},updated_at=CURRENT_TIMESTAMP,
encrypted_secret=#{cipherText},secret_iv=#{iv},secret_digest=#{digest}, encryption_algorithm=#{algorithm},masked_value=#{maskedValue},credential_version=credential_version+1,
status='ACTIVE' WHERE id=#{id}
